/// TF_DS_SPEC_SAMPLE's step hook between the step's _bias and _score (tri_markov.stepsTapped's mid): every sampled
/// stream's clean scores (its logits plus the Markov bias row _score adds: the cached row of the token the step reads,
/// else the step's staging row) and their normaliser partials into `sq` (tf_ds_spec_clean_kernel), then NoiseTap's
/// keyed noise under the draft key, so each draft is a draw from softmax(clean / T) and the verify gathers its numbers.
const SpecTap = struct {
    e: *const Engine,
    dr: *const Drafter,
    n: usize,
    ts: usize,

    fn run(ctx: *anyopaque, step: usize) anyerror!void {
        const x: *SpecTap = @ptrCast(@alignCast(ctx));
        const dr = x.dr;
        const mk = dr.mk;
        const lw = mk.rowCols();
        try x.e.ops.specClean(x.e.s, dr.local + 4 * step * lw, dr.n * lw, lw, dr.nz, dr.out + 8 * step, x.ts, mk.slot, mk.cache, dr.msc.stage, mk.cols, dr.sq + 4 * step * dr.sq_w, dr.n * dr.sq_w, x.n);
        try x.e.ops.keyedNoise(x.e.s, dr.local + 4 * step * lw, dr.n * lw, lw, mk.col0(), dr.nz, step, x.n);
    }
};

/// TF_DS_SPEC_SAMPLE: the most rows a verify speculates (every stream's held drafts) and the most elements its gather
/// takes a row: the target's candidates and the draft, then the row's normaliser partials.
pub const spec_rows = max_streams * max_block;
pub const spec_row_elems = sampling.max_candidates + 1 + 2 * ops_mod.spec_parts;
pub const spec_elems = spec_rows * spec_row_elems;

/// The per-step gather of the Markov loop's bests: [world, rows, 4] fp32 into dst.
const MarkovGather = struct {
    e: *const Engine,
    dst: u64,

    fn run(ctx: *anyopaque, send: u64, rows: usize) anyerror!u64 {
        const g: *MarkovGather = @ptrCast(@alignCast(ctx));
        try g.e.gatherF32(send, g.dst, rows * 4);
        return g.dst;
    }
};

/// The drafter pass's CUDA graphs (BatchDraftGraph), one a (streams, steps): every pointer it reads is a fixed
/// buffer and every per-pass value (ids, positions, slots, the pick lists) is uploaded ahead of the replay.
pub const PassGraphs = struct {
----
        if (keyed) |k| {
            if (k.seeds.len != N or k.temps.len != N) return error.BadDraftPass;
            var tab: [max_streams]ops_mod.KeyedRow = undefined;
            for (0..N) |i| {
                tab[i] = .{ .seed = k.seeds[i], .temp = k.temps[i], .pos = q0[i] + 1 };
                if (k.temps[i] > 0.0) noisy = true;
            }
            if (noisy) {
                if (dr.nz == 0) return error.KeyedDraftOff;
                try prompt.upload(e, dr.nz, &tab, N * @sizeOf(ops_mod.KeyedRow));
            }
        }
        if (dr.graphs != null and probe == null) try dr.graphs.?.run(dr, e, ch, pool, N, steps, noisy) else try dr.body(e, ch, pool, N, steps, probe, noisy);
        // one host read: the drafts and the confidences
        try e.s.synchronize();
        var hc: [max_streams * max_block]f32 = undefined;
        try e.d.check(e.d.api.cuMemcpyDtoH_v2(&ho, dr.out, N * ts * 8), "cuMemcpyDtoH");
        try e.d.check(e.d.api.cuMemcpyDtoH_v2(&hc, dr.conf, N * steps * 4), "cuMemcpyDtoH");
        for (0..N) |i| for (0..steps) |j| {
            dr.drafts[i][j] = ho[i * ts + 1 + j];
            dr.confs[i][j] = hc[i * steps + j];
        };
        dr.streams = N;
        dr.steps = steps;
    }

    /// TF_DS_SPEC_SAMPLE's verify gather, the same launches on every rank (rank 0's verify, a follower's spec_q frame):
    /// `idx` (lanes.specIndices: this rank's elements of the clean rows, -1 for another rank's) uploaded, this rank's
    /// values gathered from `sq`, and every rank's `wide` values all-gathered into gpeer (rank r's at r * wide).
    pub fn specGather(dr: *const Drafter, e: *const Engine, idx: []const i64, wide: usize) !void {
        if (dr.sq == 0) return error.SpecSampleOff;
        if (idx.len == 0 or idx.len > wide or wide > spec_elems or wide % 4 != 0) return error.BadSpecGather;
        try prompt.upload(e, dr.gidx, idx.ptr, idx.len * 8);
        try e.ops.gatherCols(e.s, dr.sq, dr.gidx, idx.len, dr.gout);
        try e.gatherF32(dr.gout, dr.gpeer, wide);
    }

    /// The pass's device work for N streams of `steps` drafts, from the rows' embeddings to the confidence head (its
    /// inputs uploaded: the index rows, the pick lists, the Markov loop's first column): what a pass graph captures.
    fn body(dr: *Drafter, e: *const Engine, ch: *const Chunk, pool: *const Pool, N: usize, steps: usize, probe: ?Probe, noisy: bool) !void {
        const c = e.c;
        const t = e.t;
        const n = dr.bn;
        std.debug.assert(n == dr.blockRows(steps));
        const R = N * n;
        const d = c.hidden;
        // the streams: every row's token embedding in each stream, pre (1, 0, 0, 0)
        try tri_basic.embedInit(t, e.w.embed, dr.row(0), dr.h, dr.pre, R, d, c.hc);
        // _stages_fused
        var h = dr.h;
        var spare = dr.h_alt;
        var pre = dr.pre;
        var pre_f = dr.pre_f;
        var pending: ?u64 = null;
        for (dr.ds.blocks, 0..) |lay, j| {
            h = try dr.mix(e, h, &spare, &pending, lay.hc_attn, pre, lay.attn_norm, dr.pre_a, R);
            try Probe.check(probe, .attn_in, j, dr.x);
            try Probe.check(probe, .attn_ring, j, pool.rings[j]);
            try dr.attention(e, ch, pool, j, R);
            try Probe.check(probe, .attn_out, j, dr.pa);
            if (e.two) |tw| try tw.pairGather(e, dr.pa, dr.ga, R, d, 4) else try e.gatherF32(dr.pa, dr.ga, R * d);
            try Probe.check(probe, .attn_gather, j, dr.ga);
            pending = dr.ga;
            h = try dr.mix(e, h, &spare, &pending, lay.hc_ffn, dr.pre_a, lay.ffn_norm, pre_f, R);
            try Probe.check(probe, .moe_in, j, dr.x);
            try dr.moe(e, j, R);
            try Probe.check(probe, .moe_out, j, dr.pm);
            if (e.two) |tw| try tw.pairGather(e, dr.pm, dr.gm, R, d, 4) else try e.gatherF32(dr.pm, dr.gm, R * d);
            try Probe.check(probe, .moe_gather, j, dr.gm);
            pending = dr.gm;
            std.mem.swap(u64, &pre, &pre_f);
        }
        try tri_basic.hcPost(t, dr.gm, h, dr.post, dr.comb, h, e.world, R, d);
        const S = dr.ds.blocks.len;
        try Probe.check(probe, .stages_h, S, h);
        try Probe.check(probe, .stages_pre, S, pre);
        // the head on every row (this rank's columns: the Markov loop scores them without a gather)
        try tri_basic.collapse(t, h, pre, dr.xc, R, d);
        try tri_basic.rmsnorm(t, dr.xc, d, dr.ds.norm, dr.xn, d, c.eps, R, d);
        try prompt.grouped(e, ch, R, &.{e.w.head}, &.{dr.xn}, &.{d}, &.{dr.local}, &.{e.w.head.n}, &.{.f32});
        try Probe.check(probe, .local, S, dr.local);

    return 24 * @as(u64, c.hc) * c.hidden * 4;
}

/// A round's GPU time by phase (tf-dsv41-lanes --profile 2): a timing event on the main stream at each phase's end,
/// the elapsed times read after the round. Eager rounds only (in a graph the events would be captured).
pub const PhaseTimer = struct {
    // (sh_*: the sharded attention's parts, TF_DS_KV_SHARD: the fetch or mask kernel, the fetch's row exchange, owner
    // decode's query send (on the ring: at q, before the indexer), own-head pass, query wait, peer-head pass, output
    // send (NCCL: the exchange), output wait (the ring), the NCCL path's select)
    pub const Phase = enum(u8) { start, embed, engram, mix_attn, attn, gather_a, mix_ffn, moe, gather_m, post, head, a_in, a_q, a_idx, a_core, a_woa, a_x, m_rt, m_gu, m_x, sh_fetch, sh_rows, sh_q, sh_own, sh_qwait, sh_peer, sh_out, sh_owait, sh_sel };
    pub const phases = @typeInfo(Phase).@"enum".field_names;
    comptime {
        std.debug.assert(phases.len <= 32); // Round.launches
    }

    /// The marks TF_DS_CLOCK_MARKS=4 clocks: q's end (the rest of the layer before it), the compressor and indexer's
    /// end, the attention core's end and the sharded parts between (the early query send sits between a_q and a_idx).
    pub fn shardMark(p: Phase) bool {
        return @intFromEnum(p) >= @intFromEnum(Phase.sh_fetch) or p == .a_q or p == .a_idx or p == .a_core;
    }
    const max_marks = 1024;
    events: []cuda.Event,
    phase: [max_marks]Phase = undefined,
    n: usize = 0,
    ms: [phases.len]f64 = @splat(0),
    rounds: u64 = 0,
    gpa: std.mem.Allocator,

    pub fn init(gpa: std.mem.Allocator, d: *const cuda.Driver) !PhaseTimer {
        const ev = try gpa.alloc(cuda.Event, max_marks);
        var made: usize = 0;
        errdefer {
            for (ev[0..made]) |*x| x.deinit();
            gpa.free(ev);
        }
        for (ev) |*x| {
            x.* = try cuda.Event.init(d, true);
            made += 1;
        }
        return .{ .events = ev, .gpa = gpa };
    }

    pub fn deinit(t: *PhaseTimer) void {
        for (t.events) |*x| x.deinit();
        t.gpa.free(t.events);
    }

    pub fn mark(t: *PhaseTimer, s: cuda.Stream, p: Phase) !void {
        if (t.n == max_marks) return;
        try t.events[t.n].record(s);
        t.phase[t.n] = p;
        t.n += 1;
    }

    /// The round's marks read: each phase's time is from the mark before it to its own.
    pub fn finish(t: *PhaseTimer) !void {
        if (t.n == 0) return;
        try t.events[t.n - 1].synchronize();
        for (1..t.n) |i| t.ms[@backingInt(t.phase[i])] += try cuda.Event.elapsedMs(t.events[i - 1], t.events[i]);
        t.n = 0;
        t.rounds += 1;
    }
};

/// What a stretch of a round leaves the next on the host: the stream buffers' roles, the taps written, the latest kv
/// source and selection, the indexer's pool flags and k. Every round starts from the same roles (the buffers' contents
/// never carry over), so a stretch's launches and what it leaves depend on its rows and bucket alone.
const Carry = struct {
    h: u64,
    spare: u64,
    pre: u64,
    pre_f: u64,
    ntap: usize = 0,
    sh: prompt.Shared = .{},
    kk: usize = 0,
    has_cand: bool = false,
    has_cblk: bool = false,
};

/// The rounds' stretches as CUDA graphs (the served graph.py: one capture a rows and context bucket, the round cut
/// before each Engram layer, whose rows the host reads between the stretches): a stretch is captured the first time
/// its (rows, bucket, stretch) comes up and replayed after, with what it leaves. The same launches with the same
/// arguments as the eager round, so the same bytes. At most `cap` stretches are kept (TF_DS_GRAPH_CAP, rank 1's
/// --graph-cap; 0: all): past it the least recently replayed one is destroyed and captured again when it next comes
/// up. Uncapped, the keys (rows x buckets x stretches x shard modes) add up over days of growing conversations, each
/// graph holding device and host memory until the process ends. Both ranks see the same keys in the same order, so
/// with the same cap they keep and drop the same stretches.
pub const Graphs = struct {
    gpa: std.mem.Allocator,
    lru: graph_cache.Lru(Key, Entry),

    // mode: the round's shard.Mode (auto's choice); map: TF_DS_GREEDY_ARGMAX's head (the exchange, not the logits' gather)
    // topk: TF_DS_TOPK_MERGE's kmax on the stretch that runs the head (the select's argument and the exchange's size;
    // 0 elsewhere, whose launches it does not change)
    pub const Key = struct { rows: u32, bucket: u64, stretch: u32, mode: u8 = 0, map: u8 = 0, topk: u8 = 0 };
    const Entry = struct { exec: cuda.graph.Exec, start: Carry, end: Carry };

    pub fn init(gpa: std.mem.Allocator, cap: usize) Graphs {
        return .{ .gpa = gpa, .lru = .init(cap) };
    }

    pub fn deinit(g: *Graphs) void {
        var it = g.lru.valueIterator();
        while (it.next()) |en| en.exec.deinit();
        g.lru.deinit(g.gpa);
        g.* = undefined;
    }

    /// The captured stretches.
    pub fn count(g: *const Graphs) usize {
        return g.lru.count();
    }

    fn run(g: *Graphs, key: Key, e: *const Engine, rd: *Round, ch: *const Chunk, cs: *const Caches, rings: []const u64, cy: *Carry, li: usize, end: usize) !void {
        if (g.lru.get(key)) |en| {
            if (!std.meta.eql(en.start, cy.*)) return error.GraphStateMismatch;
            try en.exec.launchOn(e.s);
            cy.* = en.end;
            rd.kk = cy.kk;
            rd.has_cand = cy.has_cand;
            rd.has_cblk = cy.has_cblk;
            return;
        }
        const start = cy.*;
        try cuda.graph.beginCapture(e.s, .thread_local);
        stretch(e, rd, ch, cs, rings, cy, li, end, null) catch |err| {
            if (cuda.graph.endCapture(e.s)) |got| {
                var x = got;
                x.deinit();
            } else |_| {}
            return err;
        };
        var graph = try cuda.graph.endCapture(e.s);
        defer graph.deinit();
        var exec = try graph.instantiate();
        errdefer exec.deinit();
        // launched before it is kept: a failed launch frees it here and leaves no handle in the cache; a graph still
        // running when destroyed (this one if the put fails, or an evicted one) is freed when it completes
        try exec.launchOn(e.s);
        if (try g.lru.put(g.gpa, key, .{ .exec = exec, .start = start, .end = cy.* })) |old| {
            var x = old.exec;
            x.deinit();
            if (std.math.isPowerOfTwo(g.lru.evicted)) std.log.info("dsv41: CUDA graphs: {d} kept (the cap), {d} destroyed for newer ones so far; a count that keeps rising means TF_DS_GRAPH_CAP is below the working set", .{ g.lru.count(), g.lru.evicted });
        } else if (std.math.isPowerOfTwo(g.lru.count()) and g.lru.count() >= 64) std.log.info("dsv41: CUDA graphs: {d} kept", .{g.lru.count()});
    }
};

/// A round's errors after which the ranks cannot go on together: the ring or the communicator dead (RingFailed,
/// CommAborted), a decode round's ring transfers out of their fixed order or row lists (RingOrder, ShardRingOrder,
/// BadRingRows: a sized send may be in flight with no receive, or the peer waits in a collect), a prompt chunk's Engram
/// rows that one rank could not read (EngramRankFault: the peer waits in the layer's allGather). Rank 0 ends the pair
/// on each (native.pair_fatal: TF_DS_PAIR_BROKEN=exit exits 75, both ranks restart); a follower stops following
/// (lanes.followPair) instead of taking the next frame.
pub const pair_ending = [_]anyerror{ error.RingFailed, error.CommAborted, error.RingOrder, error.ShardRingOrder, error.BadRingRows, error.EngramRankFault };

pub fn endsPair(err: anyerror) bool {
    for (pair_ending) |x| if (x == err) return true;
    return false;
}

/// A round of these rows through every layer and the head: rd.logits [R, vocab] and rd.taps. The caches (ring, the
/// compressed rows, the positional store) are the prompt's, extended by the rows; eh: the Engram host (the rows' n-grams
/// hashed from `seq`, the whole sequence's ids through the rows'). With `graphs` each stretch runs as its graph and a
/// probe sees only the round's end (its logits and taps).
pub fn forward(e: *const Engine, rd: *Round, ch: *const Chunk, cs: *const Caches, rings: []const u64, eh: ?*prompt.EngramHost, seq: []const i32, rows: Rows, pool_cap: usize, probe: ?Probe, graphs: ?*Graphs) !void {
    const w = e.w;
    const R = rows.ids.len;
    if (R == 0 or R > e.round_rows or rows.pos.len != R) return error.BadRound;
    rd.r = R;
    // kernels.round_rows(): up to the round's bound its rows take the row-invariant decode kernels
    const bound = tri.decode_rows;
    tri.decode_rows = e.round_rows;
    defer tri.decode_rows = bound;
    var deepest: usize = 0;
    for (rows.pos) |p| deepest = @max(deepest, @as(usize, @intCast(p)) + 1);
    // TF_DS_IDX_BUCKET_FINER: the context's own size rounded up, not its next power of two (see the switch's note)
    rd.bucket = if (rd.finer) bucketFiner(deepest, pool_cap, bucket_gran) else bucketFor(deepest, pool_cap);
    rd.has_cand = false;
    rd.has_cblk = false;
    rd.kk = 0;
    try setGlue(e, rd, rows);
    rd.smode = .off;
    rd.sring = false;
    // a round that fails part way leaves the layer cursor and the early-q flag clean for the next (a ring send still
    // awaiting its receive is left open on purpose: every later ring transfer refuses, RingOrder, and the round's
    // error ends the pair, native.pair_fatal)
    errdefer {
        rd.rcur.reset();
        rd.ss_q_out = false;
    }
    if (e.kv) |kv| try shardRound(e, rd, rows, kv);
    var cy: Carry = .{ .h = rd.h, .spare = rd.h_alt, .pre = rd.pre, .pre_f = rd.pre_f };
    // the round's Engram reads, every layer's at once (AIO): hashed and submitted once the first stretch is issued
    // (its GPU time covers the reads), landed on the host before each Engram layer's stretch (both layers at the
    // first with TF_DS_ENGRAM_BOTH)
    var ah: Ahead = .{};
    var ahead = e.c.engram_layers.slice().len == 0;
    // TF_DS_ENGRAM_SUBMIT_EARLY: the rows hashed at the drafter pass's return (rd.esh) cover every window: flatten
    // and submit them now, before stretch 0 (the hashing sat after its issue, on the round's critical path); a stash
    // that covers no window takes the inline path below, today's
    if (!ahead) if (eh) |x| {
        ahead = try engramStashed(e, x, rows, &rd.esh, &ah);
    };
    // the stretches: cut before each Engram layer, its rows read on the host before it (TF_DS_ENGRAM_BOTH: one cut,
    // before the first Engram layer, for both layers' rows)
    var li: usize = 0;
    var sn: u32 = 0;
    try rd.clock(e, Round.clock_start);
    rd.launch_mark = cuda.launch.count;
    while (li < w.layers.len) : (sn += 1) {
        var end = li + 1;
        if (rd.engram_both and li == e.c.engram_layers.slice()[0]) {
            // TF_DS_ENGRAM_BOTH: both Engram layers' rows landed at the first cut; this stretch runs the rest of the
            // round, the head included, in one go
            end = w.layers.len;
        } else {
            while (end < w.layers.len and w.layers[end].engram_wkv == null) end += 1;
        }
        if (w.layers[li].engram_wkv != null) {
            if (!ahead) try engramAhead(e, eh orelse return error.NoEngramTables, seq, rows, &ah);
            ahead = true;
            if (!(rd.engram_both and ah.both)) try engramLand(e, rd, eh orelse return error.NoEngramTables, &ah, li);
        }
        try rd.clock(e, Round.clock_wait);
        if (graphs) |g| {
            try g.run(.{ .rows = @intCast(R), .bucket = rd.bucket, .stretch = sn, .mode = @intFromEnum(rd.smode), .map = @intFromBool(rd.map), .topk = if (end == w.layers.len) rd.topk else 0 }, e, rd, ch, cs, rings, &cy, li, end);
        } else try stretch(e, rd, ch, cs, rings, &cy, li, end, probe);
        try rd.clock(e, Round.clock_tail);
        if (!ahead) try engramAhead(e, eh orelse return error.NoEngramTables, seq, rows, &ah);
        ahead = true;
        li = end;
    }
    if (graphs != null) {
        try Probe.check(probe, .logits, w.layers.len, rd.logits);
        if (cy.ntap > 0) try Probe.check(probe, .taps, w.layers.len, rd.taps);
    }
}

/// Layers li .. end of a round (the first stretch starts with the rows' streams, the last ends with the head), from
/// what the stretch before left (cy), which it updates. No host step: the Engram rows are in rd.e_in already.
fn stretch(e: *const Engine, rd: *Round, ch: *const Chunk, cs: *const Caches, rings: []const u64, cy: *Carry, li: usize, end: usize, probe: ?Probe) !void {
    const c = e.c;
    const w = e.w;
    const t = e.t;
    const R = rd.r;
    const d = c.hidden;
    if (li == 0) {
        try rd.mark(e, .start);
        try tri_basic.embedInit(t, w.embed, rd.ids, cy.h, cy.pre, R, d, c.hc);
        try rd.mark(e, .embed);
    }
    var sh = cy.sh;
    var h = cy.h;
    var spare = cy.spare;
    var pre = cy.pre;
    var pre_f = cy.pre_f;
    var ntap = cy.ntap;
    var pending: ?u64 = null;
    for (li..end) |l| {
        const lay = w.layers[l];
        rd.cur_ratio = lay.ratio;
        if (lay.engram_wkv) |ew| {
            if (pending) |gp| {
                try tri_basic.hcPost(t, gp, h, rd.post, rd.comb, h, e.world, R, d);
                pending = null;
            }
            // the slot for this layer (engram_layers is the config's order, [1, 14] here ascending as written; slot 0
            // is the first Engram layer, slot 1 the second); with the switch off e_in2 == 0 and every layer takes e_in
            var ein = rd.e_in;
            if (rd.e_in2 != 0) {
                const slot = std.mem.indexOfScalar(u16, c.engram_layers.slice(), @intCast(l));
                if (slot == 1) ein = rd.e_in2;
            }
            try prompt.grouped(e, ch, R, &.{ew}, &.{ein}, &.{ew.k}, &.{rd.ek}, &.{ew.n}, &.{.f32});
            try Probe.check(probe, .engram_proj, l, rd.ek);
            const en = if (e.two) |tw| tw.engramWidth() else ew.n;
            if (e.two) |tw| try tw.quarters(e, rd.ek, rd.ekg, R, tw.ew, 4) else try e.gatherF32(rd.ek, rd.ekg, R * ew.n);
            try Probe.check(probe, .engram_gather, l, rd.ekg);
            if (e.world != 2) return notPorted(@src());
            // TF_DS_FUSED_ROPE_STORE deliberately does not fold add2Bf16 + _engram_gate: the gate carries three
            // tl.sum reductions over the row (sh/sk/sd) plus a tl.exp sigmoid, a reduction-order replication risk
            // for two launches a forward pass (the engram layers), not the per-round hot path. Left unfused.
            try e.ops.add2Bf16(e.s, rd.ekg, rd.ekg + R * en * 4, rd.ekv, R * en);
            try tri_basic.engramGate(t, h, rd.ekv, lay.engram_qk, spare, c.eps, R, d);
            std.mem.swap(u64, &h, &spare);
            try rd.mark(e, .engram);
        }
        // the attention mixes, the pending post fused in (pre_mix)
        h = try mix(e, rd, h, &spare, &pending, lay.hc_attn, pre, lay.attn_norm, rd.pre_a, R);
        try rd.mark(e, .mix_attn);
        if (std.mem.indexOfScalar(u16, c.dspark_taps.slice(), @intCast(l)) != null) {
            // one launch a tap, straight into its block of the taps buffer
            try tri_basic.tap(t, h, rd.taps + ntap * d * 2, c.dspark_taps.slice().len * d, R, d);
            ntap += 1;
        }
        try Probe.check(probe, .attn_in, l, rd.x);
        try attention(e, rd, ch, cs, rings, &sh, l);
        try rd.mark(e, .attn);
        try Probe.check(probe, .attn_out, l, rd.pa);
        if (e.two) |tw| try tw.quarters(e, rd.pa, rd.ga, R, tw.ow, 4) else try e.gatherF32(rd.pa, rd.ga, R * d);
        try rd.mark(e, .gather_a);
        try Probe.check(probe, .attn_gather, l, rd.ga);
        pending = rd.ga;
        h = try mix(e, rd, h, &spare, &pending, lay.hc_ffn, rd.pre_a, lay.ffn_norm, pre_f, R);
        try rd.mark(e, .mix_ffn);
        try Probe.check(probe, .moe_in, l, rd.x);
        try moe(e, rd, ch, l);
        try rd.mark(e, .moe);
        try Probe.check(probe, .moe_out, l, rd.pm);
        if (e.two) |tw| try tw.quarters(e, rd.pm, rd.gm, R, tw.dw, 4) else try e.gatherF32(rd.pm, rd.gm, R * d);
        try rd.mark(e, .gather_m);
        if (rd.clk_layers) try rd.clock(e, @intCast(64 + l));
        try Probe.check(probe, .moe_gather, l, rd.gm);
        pending = rd.gm;
        std.mem.swap(u64, &pre, &pre_f);
    }
    try rd.joinSide(e); // (a stretch ends joined: the post reads the side work's post and comb)
    try rd.joinPrefetch(e);
    if (pending) |gp| try tri_basic.hcPost(t, gp, h, rd.post, rd.comb, h, e.world, R, d);
    try rd.mark(e, .post);
    cy.* = .{ .h = h, .spare = spare, .pre = pre, .pre_f = pre_f, .ntap = ntap, .sh = sh, .kk = rd.kk, .has_cand = rd.has_cand, .has_cblk = rd.has_cblk };
    if (end < w.layers.len) return;
    // the head on every row: the logits, the ranks' columns in rank order (g.permute(1, 0, 2))
    try tri_basic.collapseNorm(t, h, pre, w.norm, rd.xc, c.eps, R, d);
    const hn: usize = w.head.n;
    try prompt.grouped(e, ch, R, &.{w.head}, &.{rd.xc}, &.{d}, &.{rd.hl}, &.{hn}, &.{.f32});
    try Probe.check(probe, .head_cols, w.layers.len, rd.hl);
    const hh = if (e.two) |tw| tw.hw[0] + tw.hw[1] else hn; // a rank's vocabulary half (2D: both pairs' quarters)
    if (rd.map) {
        // TF_DS_GREEDY_ARGMAX: nothing but the pick is consumed, so the ranks' (value, index) a row travel instead of the
        // vocabulary halves - an in-place all-gather of R * 8 bytes a rank, both ranks left holding the same pairs.
        // roundArgmax's reduce turns them into the pick (the same answer the whole logits would have given).
        try e.ops.argmaxPair(e.s, rd.hl, hn, hn, R, rd.amap + e.comm.rank * R * 8);
        try e.comm.allGatherInPlace(rd.amap, R * 8, e.s);
        try rd.mark(e, .head);
        return;
    }
    if (rd.topk != 0 and probe == null) {
        // TF_DS_TOPK_MERGE: a device-drawn round reads only each row's first top_k candidates, so the ranks' best kmax
        // (value, id) pairs a row travel instead of the vocabulary halves (topk_merge.works: TP2, no 2D split, the
        // halves the vocabulary) - an in-place all-gather of R * kmax * 8 bytes a rank; Model.launchPick merges them
        const kmax: usize = rd.topk;
        if (!topk_merge_noted.swap(true, .monotonic)) std.log.info("dsv41: TF_DS_TOPK_MERGE: the head exchanges each rank's best {d} pairs a row (first at {d} rows)", .{ kmax, R });
        try e.ops.topkSelect(e.s, rd.hl, hn, hn, R, e.comm.rank * hn, kmax, rd.tpairs + e.comm.rank * R * kmax * 8);
        try e.comm.allGatherInPlace(rd.tpairs, R * kmax * 8, e.s);
        try rd.mark(e, .head);
        return;
    }
    if (e.two) |tw| try tw.quarters(e, rd.hl, rd.hg, R, tw.hw, 4) else try e.gatherF32(rd.hl, rd.hg, R * hn);
    try Probe.check(probe, .head_gather, w.layers.len, rd.hg);
    for (0..e.world) |k| try e.ops.copyRows(e.s, rd.hg + k * R * hh * 4, hh * 4, rd.logits + k * hh * 4, e.world * hh * 4, hh * 4, R);
    try rd.mark(e, .head);
    try Probe.check(probe, .logits, w.layers.len, rd.logits);
    if (ntap > 0) try Probe.check(probe, .taps, w.layers.len, rd.taps);
}

/// rounds.py pre_mix: hc_pre2 of the streams h with the pending gathered partials posted in (into the spare buffer,
/// which becomes the streams), the Sinkhorn half deferred to the side stream (this one); returns the streams.
fn mix(e: *const Engine, rd: *Round, h: u64, spare: *u64, pending: *?u64, params: [3]u64, pre_in: u64, norm: u64, pre_out: u64, R: usize) !u64 {
    const c = e.c;
    try rd.joinSide(e);

    try rd.mark(e, .a_core);
    var calls: [exl3_linear.gmax]exl3_linear.Call = undefined;
    const uw = lay.groups * lay.wo_a[0].n;
    var col: usize = 0;
    var off: usize = 0;
    for (lay.wo_a[0..lay.groups], 0..) |wo, gi| {
        const rot: exl3_linear.RotOut = if (e.two) |tw| round2d.woRot(tw, lay, col) else .{ .suh = lay.wo_b.suh, .xh = rd.xb, .ldr = @intCast(lay.wo_b.k), .off = @intCast(col) };
        calls[gi] = .{ .layer = wo, .x = 0, .ldx = 0, .x_dtype = .bf16, .xh = rd.xhwo + off * 2, .y = rd.u + col * 2, .ldy = @intCast(uw), .y_dtype = .bf16, .counters = 0, .rot = rot };
        col += wo.n;
        off += R * wo.k;
    }
    try prompt.groupedRotated(e, ch, R, calls[0..lay.groups]);
    try rd.mark(e, .a_woa);
    if (e.two) |tw| try round2d.woExchange(tw, e, rd.xb, R); // 2D: the column partner's half of wo_b's input rows
    try rd.mark(e, .a_x);
    var cb_call = [_]exl3_linear.Call{.{ .layer = lay.wo_b, .x = 0, .ldx = 0, .x_dtype = .bf16, .xh = rd.xb, .y = rd.pa, .ldy = @intCast(lay.wo_b.n), .y_dtype = .f32, .counters = 0 }};
    try prompt.groupedRotated(e, ch, R, &cb_call);
    // the prefetch behind wo_b: the ffn mix's weights, the router, the shared expert's gate
    try rd.prefetch(e, &.{ .{ lay.hc_ffn[0], hcFnBytes(c) }, .{ lay.gate_w, @as(u64, c.experts) * c.hidden * 2 }, lay.experts.shared_gate, lay.experts.shared_up, lay.experts.shared_down }, prefetch_budget / 2);
}

/// TF_DS_KV_SHARD's decode attention by sparse fetch (the reference): each rank packs the picks of the rows it holds
/// (codes and scales from its plane at the row's local base, pick order) into its slot of the gathered buffer
/// ([world][R][index_topk] rows), renumbers every row's picks to its row there (relative: j), and the other rank gets
/// them; then both ranks attend every row for their own heads over the gathered rows at the row's fetch base. On the
/// RDMA ring (rd.sring) a rank sends only its send list's rows (the rows only it holds), kk picks each, and the peer
/// puts them at its receive list's rows of the sender's slot (shard_ring.fetchXfer: one sized transfer for codes and
/// scales); on NCCL the slots are all-gathered in
/// place at their fixed size (one NCCL group). The same schedule on both ranks whoever holds the rows, every buffer
/// the round's own (graph-safe); each row reads the replicated bytes in the replicated order (shard.zig's and
/// shard_ring.zig's tests).
/// TF_DS_KV_FETCH_REUSE's key: the KV source layer, the index layer whose selection rd.cidx holds, the picks a row.
pub const FetchKey = struct {
    src: usize,
    idx: usize,
    kk: usize,

    pub fn eql(a: FetchKey, b: FetchKey) bool {
        return a.src == b.src and a.idx == b.idx and a.kk == b.kk;
    }
};

var reuse_noted = std.atomic.Value(bool).init(false);

/// TF_DS_PLACE_BOUND_ALL=1 turns the uncapped place bound on (unset, empty or anything else: off).
pub fn placeAllOn() bool {
    const v = std.c.getenv("TF_DS_PLACE_BOUND_ALL") orelse return false;
    return std.mem.eql(u8, std.mem.span(v), "1");
}

/// A decode window's most distinct expert places: each row's top_k routed slots, all distinct across rows at worst,
/// and the shared expert, one id in every row's last slot (exl3_experts: "the shared expert, the last, in every row's
/// last slot"). exl3_experts.decodeLaunches takes min(rows * slots, experts, this).
pub fn placeAll(top_k: usize, rows: usize) usize {
    return top_k * rows + 1;
}

test "TF_DS_PLACE_BOUND_ALL: top_k slots a row plus the shared expert" {
    try std.testing.expectEqual(@as(usize, 43), placeAll(6, 7)); // 49 places -> 43 at seven rows
    try std.testing.expectEqual(@as(usize, 7), placeAll(6, 1));
    try std.testing.expectEqual(@as(usize, 97), placeAll(6, 16));
}
var topk_merge_noted = std.atomic.Value(bool).init(false);

/// TF_DS_KV_FETCH_REUSE=1 turns the reuse on (unset, empty or anything else: off, the reference schedule).
pub fn fetchReuseOn() bool {
    const v = std.c.getenv("TF_DS_KV_FETCH_REUSE") orelse return false;
    return std.mem.eql(u8, std.mem.span(v), "1");
}

fn fetchDecode(e: *const Engine, rd: *Round, a: tri_attn.Attn, ratio: usize) !void {
    const c = e.c;
    const R = rd.r;
    const K = c.index_topk;
    const kk = a.n_idx;
    if (kk > K or rd.fc == 0) return error.NoKvShard;
    const cb = c.head_dim / 2;
    const sb = c.head_dim / 16;
    const final = R > tri.decode_rows;
    const kos = if (final) (kk + 15) / 16 * 16 else kk;
    const key: FetchKey = .{ .src = rd.cur_src, .idx = rd.idx_layer, .kk = kk };
    if (rd.fetch_reuse) if (rd.fetch_key) |k| if (k.eql(key)) {
        // TF_DS_KV_FETCH_REUSE: this run's rows are already gathered (same KV source, same picks, same kk)
        if (!reuse_noted.swap(true, .monotonic)) std.log.info("dsv41: TF_DS_KV_FETCH_REUSE: decode reuses a run's gathered KV rows (first at kv source {d}, index layer {d})", .{ key.src, key.idx });
        try rd.mark(e, .sh_fetch);
        try rd.mark(e, .sh_rows);
        var b = a;
        b.comp = .{ .fp4 = .{ .codes = rd.fc, .scales = rd.fs } };
        b.idx = rd.fidx;
        b.cbase = rd.sgl(.fbase);
        try tri_attn.sparseAttn(e.t, b);
        return;
    };
    const sl = shard.decodeSlots(e.kv.?.sh.rank, R, K, cb, sb);
    try shard_ops.fetch(&e.kv.?.k, e.s, .{
        .codes = a.comp.fp4.codes,
        .scales = a.comp.fp4.scales,
        .cb = cb,
        .sb = sb,
        .idx = a.idx,
        .ks = kk,
        .kk = kk,
        .rows = R,
        .sbase = rd.sgl(if (ratio == 1) .lbase1 else .lbase2),
        .own = rd.sgl(.own),
        .copy = true,
        .dcodes = rd.fc + sl.codes,
        .dscales = rd.fs + sl.scales,
        .dk = K,
        .out = rd.fidx,
        .kos = kos,
        .how = .relative,
    });
    try rd.mark(e, .sh_fetch);
    const kv = e.kv.?;
    if (rd.sring) {
        const x = shard_ring.fetchXfer(rd.fc, rd.fs, kv.sh.rank, R, K, kk, cb, sb);
        try rd.rcur.begin(.fetch);
        try rd.rcur.take(.stage_fetch);
        try shard_ops.ringSend(&kv.k, e.ring.?, e.s, x, rd.rlist + shard_ring.Lists.offset(.fetch, .send), R, true);
        try rd.rcur.take(.collect_fetch);
        try shard_ops.ringRecv(&kv.k, e.ring.?, e.s, x, rd.rlist + shard_ring.Lists.offset(.fetch, .recv), R, kv.sh.peer(), true);
    } else try e.comm.allGatherInPlace2(rd.fc, sl.slot_c, rd.fs, sl.slot_s, e.s);
    try rd.mark(e, .sh_rows);
    rd.fetch_key = if (rd.fetch_reuse) key else null;
    var b = a;
    b.comp = .{ .fp4 = .{ .codes = rd.fc, .scales = rd.fs } };
    b.idx = rd.fidx;
    b.cbase = rd.sgl(.fbase);
    try tri_attn.sparseAttn(e.t, b);
}

/// Owner decode on the RDMA ring: this rank's queries q [R][hl][hd] of the rows only the peer holds to the peer's
/// gathered queries (shard_ring.qXfer, its q send list); ownerRing's receive takes the peer's. No other ring transfer
/// runs between the two (Ring's RowPairing). Sent early (at q, behind the compressor and the indexer) on the shard
/// side stream when there is one, so its copy overlaps them too (joined before the collect), and kept out of the ring
/// probes (its doorbell-to-flag time would include the compressor and the indexer).
fn sendQueries(e: *const Engine, rd: *Round, q: u64, early: bool) !void {
    const kv = e.kv.?;
    const x = shard_ring.qXfer(q, rd.qall, kv.sh.rank, rd.r, e.heads(), e.c.head_dim);
    const list = rd.rlist + shard_ring.Lists.offset(.q, .send);
    try rd.rcur.take(.stage_q);
    if (early) if (rd.ss) |ss| {
        try rd.ss_fork.?.record(e.s);
        try ss.wait(rd.ss_fork.?);
        try shard_ops.ringSend(&kv.k, e.ring.?, ss, x, list, rd.r, false);
        try rd.ss_jq.?.record(ss);
        rd.ss_q_out = true;
        return;
    };
    try shard_ops.ringSend(&kv.k, e.ring.?, e.s, x, list, rd.r, !early);
}

/// TF_DS_KV_SHARD's owner-computed decode: the ranks' queries gathered; each rank attends the rows it holds (the
/// others' picks masked to none) for its own heads (its sinks, its wo_a rotation: the replicated call over its own
/// plane at the row's local base) and then for the other rank's heads with that rank's queries, sinks and wo_a suh
/// (the same 32-head kernels, no 64-head variant needed), whose rotated wo_a inputs go back in one exchange; a rank
/// takes the returned rows for the rows it does not hold. Every head of a row is computed by the kernel, keys and
/// order its own rank would use, so the bits are the replicated ones (GPU validation: docs/port/shard-attn.md).
/// Rounds of the split path only (the merge applies the rotation; tri.decode_rows is the round's bound).
/// On the RDMA ring (rd.sring) the exchanges are sized by the round's row lists and overlapped: ownerRing.

/// The token a row's logits draw at absolute position `position`: greedy without sampling (or at temperature 0),
/// else the served sampler with the stream's key.
pub fn draw(row: []const f32, position: u64, s: ?lanes.Sampling) !u32 {
    const sm = s orelse return @intCast(sampling.argmax(row));
    if (sm.temperature <= 0) return @intCast(sampling.argmax(row));
    const t = try sampling.sampleRow(row, position, .{ .seed = sm.seed, .temperature = sm.temperature, .top_k = sm.top_k, .top_p = sm.top_p, .min_p = sm.min_p });
    return @intCast(t);
}

/// Where rank 0's backend calls spend their time (ns, summed; --profile): a round's frame to rank 1, its forward
/// and absorb (synchronized apart), the logits' copy to the host and the draws; the drafter passes; the prefills.
pub const Profile = struct {
    send: u64 = 0,
    enqueue: u64 = 0,
    forward: u64 = 0,
    absorb: u64 = 0,
    logits: u64 = 0,
    sample: u64 = 0,
    pass: u64 = 0,
    pass_send: u64 = 0, // the pass frame's send: from its issue to the pass timer's start (0146)
    prefill: u64 = 0,
    // TF_DS_RDMA_PROBES: the ring gathers' three parts (ns, summed over the probed gathers) and how many were probed:
    // the stage, the doorbell to the peer's flags (the flight) and the copy-out
    ring_stage: u64 = 0,
    ring_flight: u64 = 0,
    ring_copy: u64 = 0,
    ring_n: u64 = 0,
    rounds: u64 = 0,
    rows: u64 = 0,
    passes: u64 = 0,
    pass_streams: u64 = 0,
    prefills: u64 = 0,
};

/// A round-cost table "30.0,35.2,..." (TF_DS_ROUND_MS's form): ms by rows from 1.
pub fn parseMs(a: std.mem.Allocator, text: []const u8) ![]const f64 {
    var out: std.ArrayList(f64) = .empty;
    var it = std.mem.splitScalar(u8, text, ',');
    while (it.next()) |x| try out.append(a, try std.fmt.parseFloat(f64, std.mem.trim(u8, x, " ")));
    if (out.items.len == 0) return error.BadRoundMs;
    return out.items;
}

/// A calibration weight ("0.5"): finite, from 0 (off) to 1 (TF_DS_T25_DRAFT_CAL).
pub fn parseCalWeight(text: []const u8) !f64 {
    const v = try std.fmt.parseFloat(f64, std.mem.trim(u8, text, " "));
    if (!std.math.isFinite(v) or v < 0.0 or v > 1.0) return error.BadDraftCal;
    return v;
}

    if (windows.len > max_streams) return error.WindowTooWide;
    var ids: [max_streams][max_rows]i32 = undefined;
    var wins: [max_streams]Win = undefined;
    try self.roundWins(windows, &ids, &wins);
    // 0177 (TF_DS_DRAFT_TRIAGE): the conf rule's dead rows (a chain survival under the threshold) ride the frame
    // as each window's live-row count, so both ranks mark the same rows. Row 0 (the pending token) never dies;
    // forced/tree rows are left alone (their rows' fate rides their parents).
    if (m.triage) |t| for (windows, wins[0..windows.len]) |w, *win| {
        win.live = if (w.parents != null or w.tokens.len > 0) 0 else @intCast(triageLive(self.streams.getPtr(w.stream).?.confs[0..w.held], t));
    };
    // every row greedy: the device's argmax (R tokens back); every sampled row one the kernel reproduces and
    // TF_DS_T27_DEVICE_DRAW on: the device's draw (R tokens back); else the logits for the host's draws. Read before
    // the forward: TF_DS_GREEDY_ARGMAX decides the head's exchange from it.
    var rules: sampling.RoundRules = .{};
    for (windows) |w| if (w.stream.sampling) |sm| rules.add(sm.temperature, sm.top_k);
    // a score stream's rows need every logit on the host
    for (windows) |w| {
        if (w.stream.score != null) rules.logits = true;
    }
    // TF_DS_SPEC_SAMPLE: a sampled round reads its logits on the host (the drafted rows' p), whatever the draw switch
    const spec = m.ops.spec and m.dr != null and m.dr.?.sq != 0;
    const path = if (spec and rules.sampled) .host_draw else rules.path(m.ops.draw_rows != null);
    // TF_DS_GREEDY_ARGMAX (0186): a greedy round consumes nothing but the pick, so its head exchanges the ranks'
    // (value, index) a row instead of the vocabulary halves; the round decides, so the stretch's graph carries it
    m.rd.map = m.argmax_map and sampling.argmaxMapWorks(m.eng.world, m.two != null, path);
    defer m.rd.map = false;
    // TF_DS_TOPK_MERGE: a device-drawn round's head exchanges each rank's best kmax candidates a row (kmax the
    // round's largest sampled top_k), decided here so the frame carries it to the follower and the graph key
    var kmax: usize = 0;
    for (windows) |w| if (w.stream.sampling) |sm| {
        kmax = topk_merge.addRow(kmax, sm.temperature, sm.top_k);
    };
    m.rd.topk = if (topk_merge.works(m.ops.topk_merge, path, m.eng.world, m.two != null, false, m.vocab, m.eng.w.head.n, kmax)) @intCast(kmax) else 0;
    defer m.rd.topk = 0;
    const t0 = m.now();
    if (try self.begin(.verify)) {
        try self.wire.int(gpa, u32, @as(u32, @intCast(windows.len)) | (@as(u32, m.rd.topk) << topk_merge.header_shift) | (@as(u32, @intFromBool(m.rd.map)) << 31));
        for (wins[0..windows.len]) |w| try writeWin(&self.wire, gpa, w, self.kv != null);
        try self.flush();
    }
    const t1 = m.now();
    if (self.spill) |t| for (wins[0..windows.len]) |w| t.bump(w.base + w.start, w.base + w.start + w.ids.len);
    const rows = try self.built.build(gpa, &self.seqs, wins[0..windows.len]);
    if (m.triage != null) {
        // (0177: the mask to the device before the forward; uploaded every round so no stale flag survives)
        var mask: [round.max_rows]u8 = @splat(0);
        for (wins[0..windows.len], 0..) |win, k| {
            if (win.live == 0) continue;
            for (win.live..win.ids.len) |r| mask[self.built.wins[k].row + r] = 1;
        }
        try m.setDead(&mask);
    }
    // 0160 (TF_DS_ABSORB_AFTER_PICK): forward, then the pick, then the taps' absorb left running under the host's
    // accept and the pass frame's send; off: the served order (forward, absorb, pick)
    try m.verify(rows);
    if (!m.absorb_after_pick) try m.absorbRows(rows, self.built.absorb[0..windows.len]);
    const t2 = m.now();
    // TF_DS_DEVICE_ACCEPT: chain windows' keep counts from the device (one kernel after the pick, in roundArgmax);
    // every window a chain and the rows' picks from the device, else the host's acceptPath decides as before
    var accept_n: usize = 0;
    if (self.accept_chain and path != .host_draw) {
        var chain = true;
        for (windows) |w| {
            if (w.parents != null) {
                chain = false;
                break;
            }
        }
        if (chain) {
            var a_row0: [max_streams]u32 = undefined;
            var a_wrows: [max_streams]u32 = undefined;
            for (0..windows.len) |k| {
                a_row0[k] = @intCast(self.built.wins[k].row);
                a_wrows[k] = @intCast(windows[k].rows());
            }
            try m.setAccept(a_row0[0..windows.len], a_wrows[0..windows.len]);
            accept_n = windows.len;
        }
    }
    defer m.accept_rows = 0;
    const n_rows = rows.ids.len;
    var draw_tab: [round.max_rows]ops.DrawRow = undefined;
    if (path == .device_draw) {
        @memset(draw_tab[0..n_rows], .{ .seed = 0, .temp = 0, .top_p = 0, .min_p = 0, .pos = 0, .top_k = 0 });
        for (windows, 0..) |w, k| {
            const sm = w.stream.sampling orelse continue;
            const row0 = self.built.wins[k].row;
            for (0..w.rows()) |r| draw_tab[row0 + r] = .{ .seed = sm.seed, .temp = sm.temperature, .top_p = sm.top_p, .min_p = sm.min_p, .pos = w.positions[r], .top_k = sm.top_k };
        }
        try m.setDraw(draw_tab[0..n_rows]);
    }
    defer m.draw_rows = 0;
    const tokens: []const u32 = if (path == .host_draw) &.{} else try m.roundArgmax(n_rows);
    m.rd.map = false; // (the round's own; the next one decides again)
    m.rd.topk = 0;
    // TF_DS_DEVICE_ACCEPT: the keeps ride the amax buffer right after the picks (roundArgmax memcpy'd them out)
    if (accept_n != 0) {
        for (0..accept_n) |k| out[k].device_keep = m.amax_host[n_rows + k];
    }
    const logits: []const f32 = if (path == .host_draw) try m.roundLogits(n_rows) else &.{};
    if (m.absorb_after_pick) try m.absorbRows(rows, self.built.absorb[0..windows.len]); // (0160: after the pick's read; runs under the host's accept and the frame send)
    if (m.rd.hot != null) { // (0179: the hot plan rebuilds every 32 rounds, on the pick's own sync)
        m.hot_age += 1;
        if (m.hot_age >= 32) {
            m.hot_age = 0;
            m.updateHot();
        }
    }
    if (m.ringFailed()) return error.RingFailed; // (robustness: a graph's collect gave up on a dead peer's flags)
    const t3 = m.now();
    defer if (self.prof) |*p| {
        p.send += t1 - t0;
        p.enqueue += m.t_enqueue;
        p.forward += m.t_forward;
        p.absorb += m.t_absorb;
        p.logits += (t3 - t2) -| (if (m.absorb_after_pick) m.t_absorb else 0); // (0160: the late absorb sits in this span and is counted in absorb_ms)
        p.sample += m.now() - t3;
        p.rounds += 1;
        p.rows += rows.ids.len;
        // TF_DS_RDMA_PROBES: the round's ring gathers, split (their sums, read back and reset). The download waits
        // for the round's kernels, so this runs only under the profile, whose figures already include that wait.
