pub fn setAccept(m: *Model, row0: []const u32, wrows: []const u32) !void {
    if (row0.len == 0) {
        m.accept_rows = 0;
        return;
    }
    if (row0.len != wrows.len or row0.len > max_streams) return error.BadAccept;
    const d = m.ctx.d;
    const n = row0.len;
