    @memcpy(tab[0..n], row0);
    @memcpy(tab[n..][0..n], wrows);
    try d.check(d.api.cuMemcpyHtoDAsync_v2(m.accept_tab, &tab, 2 * n * 4, m.stream.handle), "cuMemcpyHtoDAsync");
