/// The records a ring holds a slot for (a round at the served shape takes a few hundred ring sequences; the drain
/// cadence below keeps N = 1 within the ring at four work units) and the dump's cadence in work units (Model.pass /
/// Model.verify rounds on both ranks).
pub const trace_cap = 4096;
pub const trace_drain_units = 4;

/// TF_DS_RING_TRACE's state (ring_trace.zig): the sampled records' device ring and the proxy's host ring, both
/// preallocated at create, drained outside the timed window to the rank's JSON lines file. The proxy writes records
/// and the two progress marks; the drain (the engine's thread) reads them below min(mark) so every emitted record is
/// complete.
const TraceState = struct {
    on: bool = false,
    n: u64 = 0,
    dev: ?cuda.DeviceBuffer = null, // cap x rec_words u64
    hdr: ?cuda.DeviceBuffer = null, // u64 round cell, then [4] u64 the streams' last gather's copy-done
    host: []u64 = &.{}, // the proxy's record ring (cap x rec_words)
    gpu_host: []u64 = &.{}, // the drain's download buffer for dev
    out: [256]u8 = @splat(0),
    out_len: usize = 0,
    meta_written: bool = false,
    gpu_mark: u64 = 0, // the last drained sequence, each ring
    proxy_mark: u64 = 0,
    tick: u64 = 0, // the round cell's value
    tick_host: u64 = 0, // the async upload's source (a stable address)
    units: u64 = 0, // work units since the last dump
    streams: [8]cuda.abi.Stream = @splat(null), // the mapped streams' handles (the prev-done cells' index)
    nstreams: u32 = 0,
    graph: bool = false, // the launches under capture: a graph's (every replay carries it)
    woke: bool = false, // the proxy's next record is its first after a nap
    max_doorbell: std.atomic.Value(u64) = .init(0), // the proxy's progress: emitted records stay below both
    max_flag: std.atomic.Value(u64) = .init(0),
    banner: std.atomic.Value(bool) = .init(false),
};

