    // -- TF_DS_RING_TRACE (ring_trace.zig) ---------------------------------------------------------------------------

    /// The by-value kernel argument (all zeros when the trace is off): the record ring, the live cells, the sampling
    /// rule and this launch's key. `stream` maps to the prev-done cell the collect will stamp.
    fn traceArg(r: *Ring, stream: cuda.Stream, key: ring_trace.Key) ring_trace.Trace {
        if (!r.tr.on) return .{};
        return .{
            .recs = r.tr.dev.?.ptr,
            .round = r.tr.hdr.?.ptr,
            .prev = r.tr.hdr.?.ptr + 8,
            .n = r.tr.n,
            .cap = trace_cap,
            .rows = key.rows,
            .op = @intFromEnum(key.op),
            .layer = key.layer,
            .stream = r.streamOrd(stream),
            .flags = @intFromBool(r.tr.graph),
        };
    }

    /// The stream's prev-done cell index (first use claims the next). shortcut: past 8 distinct streams the rest
    /// share cell 0's landmark, when more are used make the map grow.
    fn streamOrd(r: *Ring, stream: cuda.Stream) i32 {
        const h = stream.handle;
        for (r.tr.streams[0..r.tr.nstreams], 0..) |s, i| if (s == h) return @intCast(i);
        if (r.tr.nstreams < r.tr.streams.len) {
            r.tr.streams[r.tr.nstreams] = h;
            r.tr.nstreams += 1;
            return @intCast(r.tr.nstreams - 1);
        }
        return 0;
    }

    /// Graphs.run / PassGraphs: the launches under capture are a graph's (their records name it; replays carry it).
    pub fn traceGraph(r: *Ring, on: bool) void {
