fn probe(r: *const Ring) DevicePtr {
    return if (r.s.probing) r.scalar(16) else 0;
}

// -- TF_DS_RING_TRACE (ring_trace.zig) --------------------------------------------------------------------------

/// The by-value kernel argument (all zeros when the trace is off, as `probe` passes null): the record ring, the
/// live cells, the sampling rule and this launch's key. `stream` picks the prev-done cell the collect stamps.
fn traceArg(r: *Ring, stream: cuda.Stream, key: ring_trace.Key) ring_trace.Trace {
    if (!r.tr.on) return .{};
    return .{
        .recs = r.tr.dev.?.ptr,
        .round = r.tr.hdr.?.ptr,
        .prev = r.tr.hdr.?.ptr + 8,
        .n = r.tr.n,
        .cap = trace_cap,
        .rows = key.rows,
        .op = @intFromEnum(key.op),
        .layer = key.layer,
        .stream = r.streamOrd(stream),
        .flags = @intFromBool(r.tr.graph),
    };
}

/// The stream's prev-done cell index (first traced use claims the next). shortcut: past 8 distinct streams the
/// rest share cell 0's landmark, when more are used make the map grow.
fn streamOrd(r: *Ring, stream: cuda.Stream) i32 {
    const h = stream.handle;
    for (r.tr.streams[0..r.tr.nstreams], 0..) |s, i| if (s == h) return @intCast(i);
    if (r.tr.nstreams < r.tr.streams.len) {
        r.tr.streams[r.tr.nstreams] = h;
        r.tr.nstreams += 1;
        return @intCast(r.tr.nstreams - 1);
    }
    return 0;
}

/// Graphs.run / PassGraphs set this around their capture: the launches recorded then are a graph's, and every
/// replay of them carries the flag (a cache miss's first run is a replay too, indistinguishable on purpose).
pub fn traceGraph(r: *Ring, on: bool) void {
    r.tr.graph = on;
}

/// The proxy's record for a sampled sequence (null when unsampled): claims the slot, carries the nap flag and
/// the engagement banner. Every event writes its own field and the identity.
fn proxyRec(r: *Ring, q: u64) ?*ring_trace.ProxyRec {
    if (!r.tr.on or !ring_trace.sampled(q, r.tr.n)) return null;
    const rec: *ring_trace.ProxyRec = @ptrCast(@alignCast(&r.tr.host[ring_trace.slot(q, r.tr.n, trace_cap) * ring_trace.rec_words]));
    if (r.tr.woke) {
        rec.flags |= 1;
        r.tr.woke = false;
    }
    rec.seq = q;
    r.traceNote(q);
    return rec;
}

/// Once a rank, at the first record: the sampling interval and buffer size with it (the hardware gate counts
/// the line to prove the arm ran).
fn traceNote(r: *Ring, q: u64) void {
    if (!r.tr.banner.swap(true, .monotonic))
        std.log.info("dsv41: TF_DS_RING_TRACE: every {d}th ring sequence recorded in {d} device and {d} proxy records a rank (first at sequence {d})", .{ r.tr.n, trace_cap, trace_cap, q });
}

/// The round boundary (Model.pass / Model.verify entry, both ranks): the records' live round number (captured
/// graphs read the cell at replay) and the dump every `trace_drain_units` units. Stream-ordered on `stream`;
/// shortcut: a side-stream kernel issued before this lands can carry the previous round number.
pub fn traceTick(r: *Ring, stream: cuda.Stream) void {
    const tr = &r.tr;
    if (!tr.on) return;
    tr.tick += 1;
    tr.tick_host = tr.tick;
    _ = r.d.api.cuMemcpyHtoDAsync_v2(tr.hdr.?.ptr, &tr.tick_host, 8, stream.handle);
    tr.units += 1;
    if (tr.units >= trace_drain_units) {
        tr.units = 0;
        r.traceDrain(false);
    }
}

/// The dump (outside the timed window): both record rings bulk-downloaded after the mapped streams' work lands
/// (no per-gather sync) and appended as JSON lines to the rank's file. The proxy's records emit below both of
