    var pathz: [257]u8 = undefined;
    @memcpy(pathz[0..tr.out_len], tr.out[0..tr.out_len]);
    pathz[tr.out_len] = 0;
    const fd = std.posix.openatZ(std.posix.AT.FDCWD, pathz[0..tr.out_len :0], .{ .ACCMODE = .WRONLY, .APPEND = true, .CREAT = true }, 0o644) catch return;
    defer _ = std.posix.system.close(fd);
    var line: [512]u8 = undefined;
    if (!tr.meta_written) {
        var w: std.Io.Writer = .fixed(&line);
        ring_trace.metaJson(r.rank, tr.n, trace_cap, &w) catch return;
        _ = std.posix.system.write(fd, &line, w.end);
        tr.meta_written = true;
    }
    var kept: [2]u64 = .{ 0, 0 };
    for (std.mem.bytesAsSlice(ring_trace.GpuRec, std.mem.sliceAsBytes(tr.gpu_host))) |rec| {
