        var w: std.Io.Writer = .fixed(&line);
        ring_trace.gpuJson(rec, &w) catch break;
        _ = std.posix.system.write(fd, &line, w.end);
        kept[0] += 1;
    }
    for (std.mem.bytesAsSlice(ring_trace.ProxyRec, std.mem.sliceAsBytes(tr.host))) |rec| {
        if (rec.seq <= tr.proxy_mark or rec.seq > settle or !ring_trace.sampled(rec.seq, tr.n)) continue;
        var w: std.Io.Writer = .fixed(&line);
        ring_trace.proxyJson(rec, &w) catch break;
        _ = std.posix.system.write(fd, &line, w.end);
        kept[1] += 1;
    }
    const dropped = [2]u64{
        ring_trace.sampledCount(tr.gpu_mark, seq, tr.n) -| kept[0],
        ring_trace.sampledCount(tr.proxy_mark, settle, tr.n) -| kept[1],
