/// A decode-size all-gather of `count` fp32 a rank into `dst`, rank after rank: the RDMA ring when the engine has
/// one and the slice fits a slot (whole float4s), else NCCL. The same bytes either way. `key` names the transfer
/// for TF_DS_RING_TRACE (the call site knows the op and layer; a transfer over NCCL records nothing).
pub fn gatherF32(e: *const Engine, src: u64, dst: u64, count: usize, key: ring_trace.Key) !void {
    if (e.ring) |r| if (count % 4 == 0 and count * 4 <= r.s.max_bytes) return r.gather(e.s, src, @intCast(count / 4), dst, key);
    return e.comm.allGather(src, dst, count, .f32, e.s);
}

