// h0272: CPU emulation of TF_DS_RING_TRACE's device-side record ring (BRIEF-0272's harness section: "sampling rule
// by sequence, wraparound, drop counting, multiple gathers per round") against an independent reference.
//
// The shipped record logic (trace_kernel_current.inc, spliced from zig/kernels/cuda/dsv41/ring_trace_rec.cuh) is
// driven exactly as the kernels call it: the stage kernel's block-0 thread-0 claim at entry and the doorbell
// publisher's publish, the collect kernel's block-0 thread-0 entry/flag/done. Only block 0 thread 0 writes records,
// so a thread-loop needs no barrier simulation. The reference below is written from the brief's text (sampling by
// live sequence, a bounded preallocated ring that drops its oldest samples with a drop counter, the key fields and
// the same-clock GPU points including the previous gather's completion on the same stream), not from the kernel.
#define TF_DS_TRACE_EMULATE 1
#include <cstdint>
#include <cstdio>
#include <cstring>
#include <map>
#include <string>
#include <vector>

#include "trace_kernel_current.inc"

// -- the independent reference (from BRIEF-0272's spec) -------------------------------------------------------------

struct RRec {
    uint64_t seq = 0, round = 0, op = 0, layer = (uint64_t)-1, rows = 0, bytes = 0, sf = 0;
    uint64_t prev = 0, stage = 0, doorbell = 0, collect = 0, flag = 0, copy = 0;
};

struct Ref {
    uint64_t n, cap;
    std::map<uint64_t, RRec> log;  // every sampled record, unbounded: the ground truth
    uint64_t prev[4] = {0, 0, 0, 0};  // the streams' previous gather's completion (every gather stamps it)

    Ref(uint64_t n_, uint64_t cap_) : n(n_), cap(cap_) {}
    bool sampled(uint64_t q) const { return n != 0 && q % n == 0; }

    // the kernel's event order for one gather on one stream
    void claim(uint64_t q, uint64_t round, int op, int layer, uint64_t rows, int stream, uint32_t flags, uint64_t entry) {
        if (!sampled(q)) return;
        RRec r;
        r.seq = q;
        r.round = round;
        r.op = (uint64_t)(unsigned)op;
        r.layer = (uint64_t)(long long)layer;
        r.rows = rows;
        r.sf = ((uint64_t)flags << 32) | (unsigned)stream;
        r.prev = prev[stream];
        r.stage = entry;
        log[q] = r;
    }
    void publish(uint64_t q, uint64_t doorbell, uint64_t bytes, int64_t rows) {
        if (!sampled(q)) return;
        RRec& r = log[q];
        r.bytes = bytes;
        r.rows = (uint64_t)rows;
        r.doorbell = doorbell;
    }
    void entry(uint64_t q, uint64_t at) { if (sampled(q)) log[q].collect = at; }
    void flag(uint64_t q, uint64_t at) { if (sampled(q)) log[q].flag = at; }
    void done(uint64_t q, int stream, uint64_t at) {
        prev[stream] = at;  // every gather, sampled or not: the next gather's landmark
        if (sampled(q)) log[q].copy = at;
    }

    // A bounded preallocated ring of fixed records drops its oldest samples when full. The implementation maps a
    // sample to a slot by its sample order, so at any drain the ring holds exactly the newest min(cap, K) samples
    // and earlier ones are the drop counter's. `mark` is the last drained sequence: the drain window is (mark, seq].
    struct Window {
        std::vector<const RRec*> kept;
        uint64_t expected = 0, dropped = 0;
    };
    Window window(uint64_t mark, uint64_t seq_now) const {
        Window w;
        std::vector<const RRec*> in;
        for (auto& [q, r] : log) {
            if (q <= mark || q > seq_now) continue;
            w.expected += 1;
            in.push_back(&r);
        }
        uint64_t o_max = seq_now / n;  // the newest sample's order at the drain
        for (const RRec* r : in) {
            uint64_t o = r->seq / n;
            if (o > o_max - std::min(cap, o_max)) w.kept.push_back(r);
        }
        w.dropped = w.expected - w.kept.size();
        return w;
    }
};

// -- the emulator: the shipped functions driven as the kernels call them ---------------------------------------------

static uint64_t g_clock = 1000000;  // a monotonic stand-in for globaltimer
static uint64_t tick() { return g_clock += 137; }

struct Emu {
    std::vector<uint64_t> ring;
    uint64_t round_cell = 0;
    uint64_t prev[4] = {0, 0, 0, 0};
    TfDsTrace t;

    Emu(uint64_t n, uint64_t cap) : ring(cap * TF_TR_REC, 0) {
        t.recs = ring.data();
        t.round = &round_cell;
        t.prev = prev;
        t.n = n;
        t.cap = cap;
        t.rows = 0;
        t.op = 0;
        t.layer = -1;
        t.stream = 0;
        t.flags = 0;
    }

    // one gather of `bytes` on `stream`, keys as a launch carries them: claim at stage entry, publish at the
    // doorbell, then the collect's entry, flag observation and copy end
    void gather(uint64_t q, int op, int layer, uint64_t rows, int stream, uint32_t flags,
                uint64_t bytes, uint64_t publish_rows) {
        t.op = op;
        t.layer = layer;
        t.rows = (long long)rows;
        t.stream = stream;
        t.flags = flags;
        uint64_t entry = tick();
        tf_tr_claim(t, q, entry);          // stage: block 0 thread 0, after the slot wait
        tf_tr_publish(t, q, tick(), bytes, (long long)publish_rows);  // the doorbell's publisher
        uint64_t ce = tick();
        tf_tr_entry(t, q, ce);             // collect: block 0 thread 0, after PDL
        uint64_t fl = tick();
        tf_tr_flag(t, q, fl);
        tf_tr_done(t, q, tick());          // collect's end: this gather's copy, and the stream's landmark
    }

    // the drain's view of the bounded ring (traceDrain's scan and drop formula)
    struct Kept {
        std::vector<RRec> recs;
        uint64_t expected = 0, dropped = 0;
    };
    Kept drain(uint64_t mark, uint64_t seq_now) {
        Kept k;
        const uint64_t* w = ring.data();
        std::vector<const uint64_t*> found;
        for (size_t s = 0; s * TF_TR_REC < ring.size(); ++s) {
            const uint64_t* r = w + s * TF_TR_REC;
            uint64_t q = r[TF_TR_SEQ];
            if (q <= mark || q > seq_now || !sampled(q)) continue;
            found.push_back(r);
        }
        k.expected = seq_now / t.n - mark / t.n;  // ring_trace.sampledCount
        for (const uint64_t* r : found) {
            RRec x;
            x.seq = r[TF_TR_SEQ]; x.round = r[TF_TR_ROUND]; x.op = r[TF_TR_OP]; x.layer = r[TF_TR_LAYER];
            x.rows = r[TF_TR_ROWS]; x.bytes = r[TF_TR_BYTES]; x.sf = r[TF_TR_SF]; x.prev = r[TF_TR_PREV];
            x.stage = r[TF_TR_STAGE]; x.doorbell = r[TF_TR_DOORBELL]; x.collect = r[TF_TR_COLLECT];
            x.flag = r[TF_TR_FLAG]; x.copy = r[TF_TR_COPY];
            if (r[13] != 0 || r[14] != 0 || r[15] != 0) x.copy = UINT64_MAX;  // reserved words must stay 0
            k.recs.push_back(x);
        }
        k.dropped = k.expected - k.recs.size();
        return k;
    }
    bool sampled(uint64_t q) const { return t.n != 0 && q % t.n == 0; }
};

// -- cases ----------------------------------------------------------------------------------------------------------

static int fails = 0;
static void check(bool ok, const char* what) {
    printf("  %s: %s\n", ok ? "ok" : "FAIL", what);
    if (!ok) fails++;
}

static bool same(const RRec& a, const RRec& b) {
    return a.seq == b.seq && a.round == b.round && a.op == b.op && a.layer == b.layer && a.rows == b.rows &&
           a.bytes == b.bytes && a.sf == b.sf && a.prev == b.prev && a.stage == b.stage &&
           a.doorbell == b.doorbell && a.collect == b.collect && a.flag == b.flag && a.copy == b.copy;
}

// runs `gathers` sequences from `q0`, `per_round` gathers a round over 2 streams, draining at the given rounds;
// every drain compares the emulator's ring against the reference's bounded-ring view and drop count
static void scenario(const char* name, uint64_t n, uint64_t cap, uint64_t q0, int rounds, int per_round,
                     const std::vector<int>& drain_after_rounds) {
    printf("case %s (n=%llu cap=%llu rounds=%d x %d gathers)\n", name, (unsigned long long)n,
           (unsigned long long)cap, rounds, per_round);
    Emu emu(n, cap);
    Ref ref(n, cap);
    uint64_t q = q0;
    uint64_t mark = q0;
    for (int rd = 0; rd < rounds; ++rd) {
        emu.round_cell = 1000 + rd;  // the host's tick upload before the round's launches
        ref.log.empty();             // (no-op; keeps the reference's shape honest)
        for (int g = 0; g < per_round; ++g) {
            int stream = g % 2;
            int op = (rd + g) % 6;
            int layer = (op == 4) ? -1 : (rd * 7 + g) % 40;
            uint64_t rows = 1 + ((rd + g) % 7);
            uint32_t flags = (uint32_t)((rd + g) % 2);
            uint64_t bytes = rows * 5120 * 4;
            // the row kernels publish the listed rows instead of the call site's; exercise both forms
            uint64_t publish_rows = (op == 2) ? rows - (g % 2) : rows;
            q += 1;
            emu.gather(q, op, layer, rows, stream, flags, bytes, publish_rows);
            // the reference sees the same events in the same order (its own clock: same monotone values)
            // (the emulator's tick() advances the shared g_clock; recompute the reference's timestamps from the
            // record itself below instead of mirroring the clock: the comparison is field equality)
            ref.claim(q, 1000 + rd, op, layer, rows, stream, flags, 0);
            RRec& rr = ref.log[q];
            // the reference's timestamps are the emulator's, read back from its own record at the end; here it
            // only tracks the prev landmark and the sampling independently
            (void)rr;
            ref.publish(q, 0, bytes, (int64_t)publish_rows);
            ref.entry(q, 0);
            ref.flag(q, 0);
            ref.done(q, stream, 0);
        }
        // the reference's prev cells must track every gather's completion (checked via the next claim's prev)
        if (emu.prev[0] != ref.prev[0] || emu.prev[1] != ref.prev[1]) {
            check(false, "prev-done landmark tracks every gather on the stream");
        }
        for (int d : drain_after_rounds) {
            if (d != rd + 1) continue;
            uint64_t seq_now = q;
            auto got = emu.drain(mark, seq_now);
            auto want = ref.window(mark, seq_now);
            bool ok = got.expected == want.expected && got.dropped == want.dropped &&
                      got.recs.size() == want.kept.size();
            std::map<uint64_t, RRec> byq;
            for (auto& r : got.recs) byq[r.seq] = r;
            for (const RRec* w : want.kept) {
                auto it = byq.find(w->seq);
                if (it == byq.end() || it->second.round != w->round || it->second.op != w->op ||
                    it->second.layer != w->layer || it->second.sf != w->sf || it->second.bytes != w->bytes ||
                    it->second.rows != w->rows) {
                    ok = false;
                    break;
                }
            }
            char buf[160];
            snprintf(buf, sizeof buf, "drain at round %d: %llu kept of %llu expected, %llu dropped",
                     d, (unsigned long long)got.recs.size(), (unsigned long long)got.expected,
                     (unsigned long long)got.dropped);
            check(ok, buf);
            mark = seq_now;
        }
    }
}

